    if any(action["name"] == new_name for action in self.custom_actions):
        logger.error(f"Custom action {new_name} already exists.")
        return ArmStatusCode.ACTION_FILE_EXIST.value

    # Rename the file
    pre_file = pathlib.Path(self.static_config_dir / f"{pre_name}.yaml")
    new_file = pathlib.Path(self.static_config_dir / f"{new_name}.yaml")
    pre_file.rename(new_file)

    # Update the custom action list
    action = next(
        (action for action in self.custom_actions if action["name"] == pre_name),
        None,
