def delete_custom_action(self, action_name: str):
    """删除自定义动作"""
    action = next(
        (action for action in self.custom_actions if action["name"] == action_name),
        None,
    )
    if not action:
        logger.error(f"Custom action {action_name} not found.")
        return ArmStatusCode.LOAD_ACTION_FILE.value

    # 删除文件
    action_file = pathlib.Path(self.static_config_dir / f"{action_name}.yaml")
