def _check_fsm_id(self, support_fsm=[816, 831, 811, 830], verbose=False):
    self.sportmodestate.take_one()
    fsmId = self.sportmodestate.msg.fsm_id
    success = fsmId in support_fsm
    if not success and verbose:
        logger.error(
            f"FSM {fsmId} is not supported, only support {support_fsm} current: {fsmId}"
        )
    return success

def _check_motor_state(self, verbose=False):
    self._.lowstate.take_one()
    # 检测从0到28号电机
    for id in list(range(29)):
        motor = self._.lowstate.msg.motor_state[id]
        if motor.motorstate != 0:
            if verbose:
                logger.error(f"Motor {id} error state: {motor.motorstate}")
            return False
    return True

def _parser_actions(self):
    self.config_dir = pathlib.Path(__file__).parent.parent / "config"
    self.static_config_dir = pathlib.Path(
        "/unitree/etc/r1_arm_example"
    )  # 不会被ota删除
    if pathlib.Path("/unitree/module/r1_arm_example").exists() is False:
        # 本机 debug 环境
        self.static_config_dir = self.config_dir / "motions" / "custom"
    else:
        if self.static_config_dir.exists() is False:
            self.static_config_dir.mkdir(parents=True, exist_ok=True)

    # unitree action files
    with open(self.config_dir / "actions_list.yaml", "r") as f:
        self.actions_list = yaml.safe_load(f)
    unitree_actions = self.actions_list["actions"]
    self._.lowstate.take_one()
    mode_machine = self._.lowstate.msg.mode_machine
    self.actions = [
        action
        for action in unitree_actions
        if "mode_machine" not in action or mode_machine in action["mode_machine"]
    ]

    self.refresh_custom_actions()
    logger.info(f"{self.get_actions()}")

def refresh_custom_actions(self):
    """刷新自定义动作列表"""
    self.custom_actions = self.actions_list.get("custom_actions", [])
    t0 = time.time()
    existing_files = {file.stem for file in self.static_config_dir.glob("*.yaml")}
    for file in self.static_config_dir.glob("*.yaml"):
        action_name = file.stem
        if not any(action["name"] == action_name for action in self.custom_actions):
            # 读取时间
            logger.info(f"Found new custom action file: {file}, adding to list.")
            try:
                with open(file, "r") as f:
                    data = yaml.safe_load(f)
                    self.custom_actions.append(
                        {"name": action_name, "time": round(data["time"][-1], 1)}
                    )
            except Exception as e:
                logger.error(f"Load custom action file {file} failed: {e}")
                continue

    # 删除 custom_actions 中不存在于 static_config_dir 的动作
    self.custom_actions = [
        action for action in self.custom_actions if action["name"] in existing_files
    ]
    logger.info(f"Parsed custom actions in {time.time() - t0:.3f}s")

    self.actions_list["custom_actions"] = self.custom_actions
    with open(self.config_dir / "actions_list.yaml", "w") as f:
        yaml.safe_dump(
            self.actions_list, f, default_flow_style=False, allow_unicode=True
        )

def _get_unitree_motion(self, action_id: int):
    # 官方动作文件存放在 motins/unitree 文件夹下，由ID查找
    motion_file = ""
    action_name = ""
    for action in self.actions:
        if action["id"] == action_id:
            if "fsm" in action:
                if not self._check_fsm_id(action["fsm"], verbose=True):
                    return ArmStatusCode.FSM_UNAVAILABLE.value, None
            action_name = action["name"]
            motion_file = (
                self.config_dir / "motions" / "unitree" / f"{action_name}.yaml"
            )
            break
    if motion_file == "":
        logger.error(f"Action ID {action_id} not found in actions list.")
        return ArmStatusCode.INVALID_ACTION_ID.value, None
    if not motion_file.exists():
        logger.error(f"Motion file {motion_file} does not exist.")
        return ArmStatusCode.LOAD_ACTION_FILE.value, None

    try:
        motion = MotionLoader(motion_file)
    except Exception as e:
        logger.error(f"Load motion file {motion_file} failed: {e}")
        return ArmStatusCode.LOAD_ACTION_FILE.value, None

    return 0, motion

def _get_custom_motion(self, action_name: str):
    motion_file = self.static_config_dir / f"{action_name}.yaml"
    if not motion_file.exists():
        return ArmStatusCode.LOAD_ACTION_FILE.value, None

    try:
        motion = MotionLoader(motion_file)
    except Exception as e:
        logger.error(f"Load motion file {motion_file} failed: {e}")
        return ArmStatusCode.LOAD_ACTION_FILE.value, None

    return 0, motion

def _update_custom_motion(self, action_name: str, times: list):
    action = next(
        (action for action in self.custom_actions if action["name"] == action_name),
        None,
    )
    if action is None:
        self.custom_actions.append(
            {"name": action_name, "time": round(times[-1], 1)}
        )
    else:
        action["time"] = round(times[-1], 1)

    self.actions_list["custom_actions"] = self.custom_actions
    with open(self.config_dir / "actions_list.yaml", "w") as f:
        yaml.safe_dump(
            self.actions_list, f, default_flow_style=False, allow_unicode=True
        )

